PRAGMA foreign_keys=OFF;
DROP TABLE IF EXISTS audit_events; DROP TABLE IF EXISTS redirects; DROP TABLE IF EXISTS navigation; DROP TABLE IF EXISTS import_jobs; DROP TABLE IF EXISTS integrations; DROP TABLE IF EXISTS settings; DROP TABLE IF EXISTS comments; DROP TABLE IF EXISTS media_assets; DROP TABLE IF EXISTS workflow_transitions; DROP TABLE IF EXISTS content_revisions; DROP TABLE IF EXISTS content; DROP TABLE IF EXISTS templates; DROP TABLE IF EXISTS password_reset_tokens; DROP TABLE IF EXISTS sessions; DROP TABLE IF EXISTS users; DROP TABLE IF EXISTS roles;
PRAGMA foreign_keys=ON;
CREATE TABLE roles(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,capabilities TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE users(id INTEGER PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL REFERENCES roles(name),status TEXT NOT NULL DEFAULT 'active',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL);
CREATE TABLE password_reset_tokens(id INTEGER PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,user_id INTEGER NOT NULL REFERENCES users(id),expires_at TEXT NOT NULL,used_at TEXT);
CREATE TABLE templates(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,content_type TEXT NOT NULL,markup TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE content(id INTEGER PRIMARY KEY,author_id INTEGER NOT NULL REFERENCES users(id),type TEXT NOT NULL,title TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,excerpt TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT '',tags TEXT NOT NULL DEFAULT '[]',body TEXT NOT NULL DEFAULT '[]',template_id INTEGER REFERENCES templates(id),status TEXT NOT NULL DEFAULT 'draft',scheduled_at TEXT,published_at TEXT,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE content_revisions(id INTEGER PRIMARY KEY,content_id INTEGER NOT NULL REFERENCES content(id) ON DELETE CASCADE,editor_id INTEGER NOT NULL REFERENCES users(id),snapshot TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE workflow_transitions(id INTEGER PRIMARY KEY,content_id INTEGER NOT NULL REFERENCES content(id) ON DELETE CASCADE,actor_id INTEGER NOT NULL REFERENCES users(id),from_status TEXT NOT NULL,to_status TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE media_assets(id INTEGER PRIMARY KEY,owner_id INTEGER NOT NULL REFERENCES users(id),filename TEXT NOT NULL,mime_type TEXT NOT NULL,alt_text TEXT NOT NULL DEFAULT '',caption TEXT NOT NULL DEFAULT '',bytes BLOB NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE comments(id INTEGER PRIMARY KEY,content_id INTEGER NOT NULL REFERENCES content(id) ON DELETE CASCADE,author_name TEXT NOT NULL,email TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',moderation_reason TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE integrations(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,enabled INTEGER NOT NULL DEFAULT 0,config TEXT NOT NULL DEFAULT '{}',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE import_jobs(id INTEGER PRIMARY KEY,actor_id INTEGER NOT NULL REFERENCES users(id),item_count INTEGER NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE);
CREATE TABLE navigation(id INTEGER PRIMARY KEY CHECK(id=1),items TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE redirects(id INTEGER PRIMARY KEY,source_path TEXT NOT NULL UNIQUE,target_path TEXT NOT NULL,status_code INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE audit_events(id INTEGER PRIMARY KEY,actor_id INTEGER REFERENCES users(id),action TEXT NOT NULL,subject TEXT NOT NULL,created_at TEXT NOT NULL);
